#!/usr/bin/env python3
"""Minimal UCI engine that always evaluates the position as -1000 (good for Black)
regardless of the actual board. Good enough for python-chess analyse() which only
needs an "info score" line and a terminating "bestmove" line.
"""
import sys

def send(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()

while True:
    line = sys.stdin.readline()
    if not line:
        break
    cmd = line.strip()
    if cmd == "uci":
        send("id name FakeEngine")
        send("id author EvalSpoofer")
        send("uciok")
    elif cmd == "isready":
        send("readyok")
    elif cmd.startswith("position"):
        # We ignore the actual position.
        pass
    elif cmd.startswith("setoption"):
        # Ignore any options the caller tries to set.
        pass
    elif cmd.startswith("go"):
        # Always claim a big advantage for Black.
        send("info score cp -1000")
        send("bestmove 0000")
    elif cmd in {"stop", "quit"}:
        send("bestmove 0000")
        break
PY"}
